<?php

declare(strict_types=1);

namespace Cipi\Sdk\Resources;

final class BasicAuth extends Resource
{
    /**
     * {"data": {enabled, users}}; cipi/api 1.43+ adds agent: {mode,
     * public_prefix}, whether the cipi/agent routes are left out of basic auth
     * (see agent() for the same on its own).
     *
     * @return array<string, mixed>
     */
    public function status(string $app): array
    {
        return $this->client->get($this->appPath($app).'/basicauth');
    }

    /**
     * Password is generated by the panel when omitted, and returned once.
     * data.notice (cipi/api 1.43+) says when the server enabled it but did
     * not print the credentials (Cipi CLI 5.11–5.12): set the password again.
     *
     * @return array<string, mixed>
     */
    public function enable(string $app, ?string $user = null, ?string $password = null): array
    {
        return $this->client->post(
            $this->appPath($app).'/basicauth/enable',
            $this->withoutNulls([
                'user' => $user,
                'password' => $password,
            ]),
        );
    }

    /**
     * @return array<string, mixed>
     */
    public function disable(string $app): array
    {
        return $this->client->post($this->appPath($app).'/basicauth/disable');
    }

    /**
     * Whether the cipi/agent routes are left out of basic auth (API 1.41+): {mode, public, prefix}.
     *
     * @return array<string, mixed>
     */
    public function agent(string $app): array
    {
        return $this->client->get($this->appPath($app).'/basicauth/agent');
    }

    /**
     * @param  'public'|'protected'  $mode
     * @return array<string, mixed>
     */
    public function setAgent(string $app, string $mode): array
    {
        return $this->client->put($this->appPath($app).'/basicauth/agent', ['mode' => $mode]);
    }
}
